<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/functions.php';
function settings_all(): array { $rows=db()->query('SELECT setting_key,setting_value FROM settings')->fetchAll();$out=[];foreach($rows as $r){$v=json_decode($r['setting_value'],true);$out[$r['setting_key']]=json_last_error()===JSON_ERROR_NONE?$v:$r['setting_value'];}return $out; }
function setting(string $key,$default=''){ $st=db()->prepare('SELECT setting_value FROM settings WHERE setting_key=? LIMIT 1');$st->execute([$key]);$v=$st->fetchColumn();if($v!==false)return json_decode((string)$v,true)??$v;$env=['mpAccessToken'=>'MP_ACCESS_TOKEN','pixKey'=>'PIX_KEY','pixName'=>'PIX_NAME','pixCity'=>'PIX_CITY'];return getenv($env[$key]??'')?:$default; }
function save_settings(array $next): array { $pdo=db();foreach($next as $k=>$v){$json=is_string($v)?$v:json_encode($v,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);$pdo->prepare('INSERT INTO settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)')->execute([$k,$json]);}return settings_all(); }
function plans_live(): array { $s=settings_all();$prices=$s['planPrices']??[];return [['id'=>'monthly','name'=>'Mensal','days'=>30,'price'=>(float)($prices['monthly']??29.9),'description'=>'Acesso completo por 30 dias'],['id'=>'quarterly','name'=>'Trimestral','days'=>90,'price'=>(float)($prices['quarterly']??79.9),'description'=>'Acesso completo por 90 dias'],['id'=>'yearly','name'=>'Anual','days'=>365,'price'=>(float)($prices['yearly']??249.9),'description'=>'Acesso completo por 1 ano']]; }
function get_plan_live(string $id): ?array { foreach(plans_live() as $p)if($p['id']===$id)return $p;return null; }
function mp_create_pix(array $order): array { $token=trim((string)setting('mpAccessToken',''));if($token==='')throw new RuntimeException('Mercado Pago não configurado.');$body=['transaction_amount'=>round((float)$order['price'],2),'description'=>substr((string)$order['description'],0,250),'payment_method_id'=>'pix','payer'=>['email'=>(string)$order['email']],'external_reference'=>(string)$order['id']];$ch=curl_init('https://api.mercadopago.com/v1/payments');curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_RETURNTRANSFER=>true,CURLOPT_HTTPHEADER=>['Authorization: Bearer '.$token,'Content-Type: application/json','X-Idempotency-Key: '.$order['id']],CURLOPT_POSTFIELDS=>json_encode($body),CURLOPT_TIMEOUT=>20]);$raw=curl_exec($ch);$status=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);$err=curl_error($ch);curl_close($ch);if($raw===false||$status<200||$status>=300)throw new RuntimeException($err?:'Mercado Pago HTTP '.$status);$d=json_decode($raw,true);$tx=$d['point_of_interaction']['transaction_data']??[];return ['paymentId'=>(string)($d['id']??''),'status'=>(string)($d['status']??''),'qrCode'=>$tx['qr_code']??'','qrCodeBase64'=>$tx['qr_code_base64']??'','ticketUrl'=>$tx['ticket_url']??'']; }
function mp_get_payment(string $id): array { $token=trim((string)setting('mpAccessToken',''));if($token==='')throw new RuntimeException('Mercado Pago não configurado.');$ch=curl_init('https://api.mercadopago.com/v1/payments/'.rawurlencode($id));curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_HTTPHEADER=>['Authorization: Bearer '.$token],CURLOPT_TIMEOUT=>15]);$raw=curl_exec($ch);$status=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);if($raw===false||$status<200||$status>=300)throw new RuntimeException('Mercado Pago HTTP '.$status);$d=json_decode($raw,true);return is_array($d)?$d:[]; }
function order_to_array(array $r): array { return ['id'=>$r['id'],'username'=>$r['username'],'email'=>$r['email'],'planId'=>$r['plan_id'],'planName'=>$r['plan_name'],'days'=>(int)$r['days'],'price'=>(float)$r['price'],'description'=>$r['description'],'status'=>$r['status'],'paymentId'=>$r['payment_id'],'mpStatus'=>$r['mp_status'],'paymentError'=>$r['payment_error'],'paidAt'=>$r['paid_at'],'expiresAtAfter'=>$r['expires_at_after'],'createdAt'=>$r['created_at'],'updatedAt'=>$r['updated_at']]; }
function save_order(array $o): void { db()->prepare('INSERT INTO orders(id,username,email,plan_id,plan_name,days,price,description,status,payment_id,mp_status,payment_error,paid_at,expires_at_after) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE status=VALUES(status),payment_id=VALUES(payment_id),mp_status=VALUES(mp_status),payment_error=VALUES(payment_error),paid_at=VALUES(paid_at),expires_at_after=VALUES(expires_at_after)')->execute([(string)$o['id'],(string)$o['username'],(string)$o['email'],(string)$o['planId'],(string)$o['planName'],(int)$o['days'],(float)$o['price'],(string)$o['description'],(string)$o['status'],$o['paymentId']??null,$o['mpStatus']??null,$o['paymentError']??null,$o['paidAt']??null,$o['expiresAtAfter']??null]); }
function get_order(string $id): ?array { $st=db()->prepare('SELECT * FROM orders WHERE id=? LIMIT 1');$st->execute([$id]);$r=$st->fetch();return $r?order_to_array($r):null; }
function fulfill_order(array $o): array { if(($o['status']??'')==='paid')return $o;$target=get_user((string)$o['username']);if(!$target)throw new RuntimeException('Usuário não encontrado.');$days=max(1,(int)$o['days']);$cur=!empty($target['expiresAt'])?strtotime((string)$target['expiresAt']):time();$base=max($cur,time());$target['expiresAt']=date('Y-m-d H:i:s',$base+$days*86400);$target['plan']=$o['planId'];$target['active']=true;save_user($target);$o['status']='paid';$o['paidAt']=date('Y-m-d H:i:s');$o['expiresAtAfter']=$target['expiresAt'];save_order($o);return $o;}
